import os
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

from google.cloud import logging_v2


class GoogleCloudLoggingClient:
    def __init__(self, project_id: Optional[str] = None) -> None:
        self.project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT") or os.getenv("GCLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("project_id is required or set GOOGLE_CLOUD_PROJECT/GCLOUD_PROJECT")
        self.client = logging_v2.Client(project=self.project_id)

    @staticmethod
    def _to_rfc3339(value: Any) -> str:
        if isinstance(value, datetime):
            dt = value
        elif isinstance(value, (int, float)):
            dt = datetime.fromtimestamp(value, tz=timezone.utc)
        elif isinstance(value, str):
            return value
        else:
            raise TypeError("time values must be datetime, unix timestamp, or RFC3339 string")

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    @staticmethod
    def _quote_filter_value(value: Any) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (int, float)):
            return str(value)
        s = str(value).replace("\\", "\\\\").replace('"', '\\"')
        return f'"{s}"'

    def _build_filter(
        self,
        field_filters: Optional[Dict[str, Any]] = None,
        start_time: Optional[Any] = None,
        end_time: Optional[Any] = None,
        base_filter: Optional[str] = None,
    ) -> str:
        parts: List[str] = []

        if base_filter:
            parts.append(f"({base_filter})")

        if start_time is not None:
            parts.append(f'timestamp >= "{self._to_rfc3339(start_time)}"')
        if end_time is not None:
            parts.append(f'timestamp <= "{self._to_rfc3339(end_time)}"')

        for field, value in (field_filters or {}).items():
            parts.append(f"{field}={self._quote_filter_value(value)}")

        return " AND ".join(parts) if parts else ""

    def list_recent_logs(
        self,
        field_filters: Optional[Dict[str, Any]] = None,
        start_time: Optional[Any] = None,
        end_time: Optional[Any] = None,
        page_size: int = 100,
        order_by: str = "timestamp desc",
        resource_names: Optional[List[str]] = None,
        base_filter: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        query_filter = self._build_filter(
            field_filters=field_filters,
            start_time=start_time,
            end_time=end_time,
            base_filter=base_filter,
        )

        entries = self.client.list_entries(
            resource_names=resource_names or [f"projects/{self.project_id}"],
            filter_=query_filter,
            order_by=order_by,
            page_size=page_size,
        )

        results: List[Dict[str, Any]] = []
        for entry in entries:
            ts = getattr(entry, "timestamp", None)
            results.append(
                {
                    "log_name": getattr(entry, "log_name", None),
                    "timestamp": ts.isoformat() if ts else None,
                    "severity": str(getattr(entry, "severity", "")) if getattr(entry, "severity", None) is not None else None,
                    "insert_id": getattr(entry, "insert_id", None),
                    "resource": getattr(getattr(entry, "resource", None), "labels", None),
                    "labels": getattr(entry, "labels", None),
                    "payload": getattr(entry, "payload", None),
                    "trace": getattr(entry, "trace", None),
                    "span_id": getattr(entry, "span_id", None),
                }
            )
        return results


def retrieve_recent_logs(
    project_id: Optional[str] = None,
    field_filters: Optional[Dict[str, Any]] = None,
    start_time: Optional[Any] = None,
    end_time: Optional[Any] = None,
    page_size: int = 100,
    order_by: str = "timestamp desc",
    resource_names: Optional[List[str]] = None,
    base_filter: Optional[str] = None,
) -> List[Dict[str, Any]]:
    client = GoogleCloudLoggingClient(project_id=project_id)
    return client.list_recent_logs(
        field_filters=field_filters,
        start_time=start_time,
        end_time=end_time,
        page_size=page_size,
        order_by=order_by,
        resource_names=resource_names,
        base_filter=base_filter,
    )
